int allow_default_keys()
{
    int allowed = 0;

    // allow default keys if not playing a level and not in select screen
    if (level == NULL)
    {
        allowed = !selectScreen;
    }
    // during levels only allow default keys in pause
    else
    {
       allowed = _pause;
    }

    return allowed;
}

